const STORAGE_KEYS = {pc:'gamefit_pc_v2', favorites:'gamefit_favorites_v2', theme:'gamefit_theme_v2'};
const $ = id => document.getElementById(id);
let supabaseClient=null,signedInUser=null,cloudSyncReady=false,cloudSaveTimer=null;
function updateAuthView(message){
  const status=$('authStatus');if(status&&message)status.textContent=message;
  const out=$('authLoggedOut'),inside=$('authLoggedIn'),section=$('authPanel');
  if(out)out.classList.toggle('hidden',!!signedInUser);
  if(inside)inside.classList.toggle('hidden',!signedInUser);
  if(section)section.classList.toggle('hidden',!!signedInUser);
  const identity=$('authIdentity');if(identity)identity.textContent=signedInUser?'Вошли как '+signedInUser.email:'';
  const profile=$('profileMenu'),avatar=$('profileAvatarBtn'),link=$('accountLink'),email=$('profileMenuEmail');
  if(profile)profile.classList.toggle('hidden',!signedInUser);
  if(link)link.classList.toggle('hidden',!!signedInUser);
  if(avatar){const label=(signedInUser&&(signedInUser.email||'U').trim()[0]||'U').toUpperCase();avatar.textContent=label;avatar.setAttribute('aria-label','Профиль: '+(signedInUser.email||'аккаунт'));}
  if(email)email.textContent=signedInUser?signedInUser.email:'';
}
function authMessage(error){const m=String(error&&error.message||'');if(/invalid login credentials/i.test(m))return 'Неверная почта или пароль.';if(/email not confirmed/i.test(m))return 'Подтверди почту по ссылке из письма.';if(/password should be at least/i.test(m))return 'Пароль должен содержать не менее 8 символов.';if(/user already registered/i.test(m))return 'Эта почта уже зарегистрирована. Попробуй войти.';return 'Не удалось выполнить действие. Проверь настройки Supabase и подключение.';}
async function loadCloudData(){if(!supabaseClient||!signedInUser)return;const {data,error}=await supabaseClient.from('gamefit_user_data').select('pc,favorites,theme').eq('user_id',signedInUser.id).maybeSingle();if(error){cloudSyncReady=false;updateAuthView('Вход выполнен, но не удалось загрузить облачные данные. Проверь таблицу и RLS.');return;}if(data){safeWrite(STORAGE_KEYS.pc,data.pc||{});safeWrite(STORAGE_KEYS.favorites,Array.isArray(data.favorites)?data.favorites:[]);safeWrite(STORAGE_KEYS.theme,data.theme==='light'?'light':'dark');loadPc();initTheme();renderGames();}cloudSyncReady=true;if(!data)await saveCloudData();else updateAuthView('Аккаунт подключён. Профиль ПК, избранное и тема синхронизируются.');}
async function saveCloudData(){if(!supabaseClient||!signedInUser||!cloudSyncReady)return;const payload={user_id:signedInUser.id,pc:getPc(),favorites:getFavorites(),theme:document.body.classList.contains('light')?'light':'dark',updated_at:new Date().toISOString()};const {error}=await supabaseClient.from('gamefit_user_data').upsert(payload,{onConflict:'user_id'});if(error)updateAuthView('Облако временно недоступно. Локальная копия осталась на устройстве.');else updateAuthView('Изменения синхронизированы с облаком.');}
function queueCloudSync(){if(!signedInUser||!cloudSyncReady)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(saveCloudData,700);}
async function finishSignIn(user){signedInUser=user||null;cloudSyncReady=false;updateAuthView(signedInUser?'Вход выполнен. Загружаем профиль…':'Выполнен выход. Локальные данные сохранены.');if(signedInUser)await loadCloudData();}
function initAuth(){
  // Сначала подключаем обработчики, чтобы кнопка не зависела от скорости ответа Supabase.
  $('googleSignInBtn').addEventListener('click',async()=>{
    if(!supabaseClient){updateAuthView('Подключение Supabase ещё не готово. Обнови страницу через несколько секунд.');return;}
    updateAuthView('Открываем безопасный вход Google…');
    try{
      const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname}});
      if(error)updateAuthView('Ошибка входа Google: '+authMessage(error));
    }catch(error){
      updateAuthView('Не удалось открыть Google: '+authMessage(error));
    }
  });
  $('signUpBtn').addEventListener('click',async()=>{
    if(!supabaseClient){updateAuthView('Подключение Supabase ещё не готово. Обнови страницу через несколько секунд.');return;}
    const email=$('authEmail').value.trim(),password=$('authPassword').value;
    if(!email||password.length<8){updateAuthView('Введи почту и пароль не короче 8 символов.');return;}
    try{
      const {data,error}=await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});
      if(error){updateAuthView(authMessage(error));return;}
      if(data.session)await finishSignIn(data.session.user);
      else updateAuthView('Открой письмо от Supabase и подтверди адрес электронной почты.');
    }catch(error){updateAuthView(authMessage(error));}
  });
  $('signInBtn').addEventListener('click',async()=>{
    if(!supabaseClient){updateAuthView('Подключение Supabase ещё не готово.');return;}
    const email=$('authEmail').value.trim(),password=$('authPassword').value;
    if(!email||!password){updateAuthView('Введи почту и пароль.');return;}
    try{
      const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});
      if(error){updateAuthView(authMessage(error));return;}
      await finishSignIn(data.user);
    }catch(error){updateAuthView(authMessage(error));}
  });
  const signOut=async()=>{
    if(!supabaseClient)return;
    try{
      const {error}=await supabaseClient.auth.signOut();
      if(error){updateAuthView('Не удалось выйти. Попробуй ещё раз.');return;}
      $('profileDropdown')?.classList.add('hidden');
      await finishSignIn(null);
    }catch(error){updateAuthView(authMessage(error));}
  };
  $('signOutBtn').addEventListener('click',signOut);
  $('profileSignOutBtn').addEventListener('click',signOut);
  $('profileAvatarBtn').addEventListener('click',()=>{
    const menu=$('profileDropdown');
    const willOpen=menu.classList.contains('hidden');
    menu.classList.toggle('hidden',!willOpen);
    $('profileAvatarBtn').setAttribute('aria-expanded',String(willOpen));
  });
  document.addEventListener('click',event=>{
    const wrap=$('profileMenu');
    if(wrap&&!wrap.contains(event.target)){
      $('profileDropdown')?.classList.add('hidden');
      $('profileAvatarBtn')?.setAttribute('aria-expanded','false');
    }
  });
  document.addEventListener('keydown',event=>{
    if(event.key==='Escape'){
      $('profileDropdown')?.classList.add('hidden');
      $('profileAvatarBtn')?.setAttribute('aria-expanded','false');
    }
  });

  const config=window.GAMEFIT_SUPABASE_CONFIG||{};
  if(!window.supabase){
    updateAuthView('Не загрузилась библиотека авторизации. Проверь подключение к интернету и обнови страницу.');
    return;
  }
  if(!config.url||!config.anonKey||config.url.includes('YOUR_PROJECT')||config.anonKey.includes('YOUR_SUPABASE')){
    updateAuthView('Локальный режим активен. Настройки Supabase не заполнены.');
    return;
  }
  try{
    supabaseClient=window.supabase.createClient(config.url,config.anonKey);
    supabaseClient.auth.onAuthStateChange((_event,session)=>{
      setTimeout(()=>finishSignIn(session&&session.user),0);
    });
    const {data,error}=await supabaseClient.auth.getSession();
    if(error)updateAuthView('Supabase подключён, но не удалось проверить сессию: '+authMessage(error));
    else if(data.session)await finishSignIn(data.session.user);
    else updateAuthView('Войди через Google или электронную почту.');
  }catch(error){
    supabaseClient=null;
    updateAuthView('Не удалось подключить Supabase: '+authMessage(error));
  }
}


let activeFilter = 'all';
let selectedGameId = GAME_DATA[0].id;
let installPrompt = null;

function safeRead(key, fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback;}catch(_){return fallback;}}
function safeWrite(key, value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch(_){return false;}}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600);}
function getPc(){return {cpu:$('cpuInput').value.trim(),gpu:$('gpuInput').value.trim(),ram:Number($('ramInput').value)||null,storage:Number($('storageInput').value)||null,os:$('osInput').value,gpuType:$('gpuTypeInput').value};}
function savePc(showToast=true){const ok=safeWrite(STORAGE_KEYS.pc,getPc());$('saveState').textContent=ok?'● Сохранение включено':'● Не удалось сохранить';queueCloudSync();if(showToast)toast(ok?'Профиль ПК сохранён в этом браузере.':'Браузер не разрешил сохранить профиль.');}
function loadPc(){const pc=safeRead(STORAGE_KEYS.pc,{});$('cpuInput').value=pc.cpu||'';$('gpuInput').value=pc.gpu||'';$('ramInput').value=pc.ram||'';$('storageInput').value=pc.storage||'';$('osInput').value=pc.os||'unknown';$('gpuTypeInput').value=pc.gpuType||'unknown';}
function getFavorites(){const fav=safeRead(STORAGE_KEYS.favorites,[]);return Array.isArray(fav)?fav:[];}
function toggleFavorite(id){let fav=getFavorites();fav=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];safeWrite(STORAGE_KEYS.favorites,fav);queueCloudSync();renderGames();toast(fav.includes(id)?'Добавлено в избранное.':'Удалено из избранного.');}
const gameCoverCache = new Map();
const GAME_COVER_CACHE_KEY='gamefit_cover_urls_v1';
async function resolveGameCover(game){
  if(game.image)return game.image;
  if(gameCoverCache.has(game.id))return gameCoverCache.get(game.id);
  try{
    const saved=JSON.parse(localStorage.getItem(GAME_COVER_CACHE_KEY)||'{}');
    if(saved[game.id]&&saved[game.id].url&&saved[game.id].expires>Date.now()){
      gameCoverCache.set(game.id,saved[game.id].url);
      return saved[game.id].url;
    }
  }catch(_){}
  try{
    const steamUrl='https://store.steampowered.com/api/storesearch/?term='+encodeURIComponent(game.name)+'&l=english&cc=US';
    // Steam does not send browser CORS headers; use a read-only public CORS relay.
    const response=await fetch('https://proxy.cors.dev/'+steamUrl,{credentials:'omit'});
    if(!response.ok)throw new Error('Steam cover lookup unavailable');
    const data=await response.json();
    const candidates=Array.isArray(data.items)?data.items:[];
    const normalized=game.name.toLowerCase().replace(/[^a-z0-9]+/g,'');
    const match=candidates.find(item=>(item.name||'').toLowerCase().replace(/[^a-z0-9]+/g,'')===normalized)||candidates[0];
    const url=match&&match.id?'https://cdn.akamai.steamstatic.com/steam/apps/'+match.id+'/header.jpg':null;
    gameCoverCache.set(game.id,url);
    if(url){
      try{
        const saved=JSON.parse(localStorage.getItem(GAME_COVER_CACHE_KEY)||'{}');
        saved[game.id]={url,expires:Date.now()+30*24*60*60*1000};
        localStorage.setItem(GAME_COVER_CACHE_KEY,JSON.stringify(saved));
      }catch(_){}
    }
    return url;
  }catch(_){gameCoverCache.set(game.id,null);return null;}
}
async function loadGameCovers(items){
  await Promise.all(items.filter(g=>!g.image).map(async game=>{
    const url=await resolveGameCover(game);
    if(!url)return;
    const img=document.querySelector('[data-game-cover="'+game.id+'"]');
    if(img){img.src=url;img.style.display='block';}
    if(selectedGameId===game.id)updateQuickPreview();
  }));
}
function renderGames(){
  const query=$('gameSearch').value.trim().toLowerCase();const fav=getFavorites();
  const items=GAME_DATA.filter(g=>(activeFilter==='all'||(activeFilter==='favorites'?fav.includes(g.id):g.tags.includes(activeFilter)))&&(`${g.name} ${g.genre} ${g.description}`.toLowerCase().includes(query)));
  $('gameGrid').innerHTML=items.map(g=>`<article class="game-card"><div class="game-banner" style="background:${g.color}"><span class="game-emoji" aria-hidden="true">${g.emoji}</span><img class="game-art-image" data-game-cover="${g.id}" src="${g.image||''}" alt="Обложка игры ${escapeHtml(g.name)}" loading="lazy" referrerpolicy="no-referrer" style="${g.image?'':'display:none'}" onerror="this.style.display='none'"><span class="game-type">${escapeHtml(g.genre.toUpperCase())}</span></div><div class="game-content"><h3>${escapeHtml(g.name)}</h3><p>${escapeHtml(g.description)}</p><div class="game-meta">${g.min?`<span class="meta-pill">RAM: ${g.min.ram} ГБ минимум</span><span class="meta-pill">${g.rec?'Есть рекомендованные':'Минимум'}</span>`:'<span class="meta-pill">Требования уточняются</span>'}</div><div class="game-actions"><button class="button secondary" data-open-game="${g.id}">${g.min?'Требования →':'Подробнее →'}</button><button class="favorite-btn ${fav.includes(g.id)?'active':''}" data-fav="${g.id}" aria-label="${fav.includes(g.id)?'Убрать из':'Добавить в'} избранное">${fav.includes(g.id)?'★':'☆'}</button></div></div></article>`).join('');
  $('emptyState').classList.toggle('hidden',items.length>0);
  loadGameCovers(items);
}
function renderQuickSelect(){ $('quickGameSelect').innerHTML=GAME_DATA.map(g=>`<option value="${g.id}">${escapeHtml(g.name)}</option>`).join('');updateQuickPreview();}
function getGame(id){return GAME_DATA.find(g=>g.id===id)||GAME_DATA[0];}
function updateQuickPreview(){selectedGameId=$('quickGameSelect').value;const g=getGame(selectedGameId);const cover=g.image||gameCoverCache.get(g.id);$('quickGameArt').style.background=g.color;$('quickGameArt').innerHTML=`<span class="preview-fallback" aria-hidden="true">${g.emoji}</span>${cover?`<img src="${cover}" alt="Обложка ${escapeHtml(g.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.display='none'">`:''}`;$('quickGameTitle').textContent=g.name;$('quickGameDesc').textContent=g.description;if(!cover)resolveGameCover(g).then(url=>{if(url&&selectedGameId===g.id)updateQuickPreview();});}
function renderReqLine(label,value){return `<div class="req-row"><span>${label}</span><b>${escapeHtml(value??'Не указано')}</b></div>`;}
function openGameDetail(id){const g=getGame(id);$('quickGameSelect').value=g.id;updateQuickPreview();$('checker').scrollIntoView({behavior:'smooth'});$('resultPanel').classList.remove('hidden');if(!g.min){$('resultPanel').innerHTML=`<div class="detail-head"><div><div class="panel-kicker">КАТАЛОГ · ТРЕБОВАНИЯ НЕ ПРОВЕРЕНЫ</div><h3>${g.emoji} ${escapeHtml(g.name)}</h3><p class="result-summary">${escapeHtml(g.description)}</p></div><button class="text-button" id="closeDetail">Скрыть ×</button></div><div class="requirement-card"><h4>Системные требования пока не добавлены</h4><p class="muted">Мы не будем придумывать характеристики. Открой страницу игры и проверь официальные сведения перед покупкой.</p><a class="button secondary" href="${g.url}" target="_blank" rel="noopener noreferrer">Найти игру в Steam ↗</a></div><p class="result-foot">GameFit пока не сравнивает этот компьютер с требованиями данной игры.</p>`;$('closeDetail').addEventListener('click',()=>{$('resultPanel').classList.add('hidden');});return;}$('resultPanel').innerHTML=`<div class="detail-head"><div><div class="panel-kicker">СИСТЕМНЫЕ ТРЕБОВАНИЯ · ${escapeHtml(g.updated)}</div><h3>${g.emoji} ${escapeHtml(g.name)}</h3><p class="result-summary">${escapeHtml(g.description)} <a href="${g.url}" target="_blank" rel="noopener noreferrer">Открыть источник ↗</a></p></div><button class="text-button" id="closeDetail">Скрыть ×</button></div><div class="requirements-columns">${renderRequirementsColumn('Минимальные требования',g.min)}${g.rec?renderRequirementsColumn('Рекомендуемые требования',g.rec):'<div class="requirement-card"><h4>Рекомендованные требования</h4><p class="muted">Издатель не указывает отдельные рекомендованные характеристики на выбранной странице.</p></div>'}</div><p class="result-foot">Источник: ${escapeHtml(g.source)}. Значения могут измениться после обновлений игры. Проверь страницу источника перед покупкой.</p>`;$('closeDetail').addEventListener('click',()=>{$('resultPanel').classList.add('hidden');});}
function renderRequirementsColumn(title,spec){return `<div class="requirement-card"><h4>${title}</h4>${renderReqLine('Процессор',spec.cpu)}${renderReqLine('Оперативная память',spec.ram+' ГБ')}${renderReqLine('Видеокарта',spec.gpu)}${renderReqLine('Место на диске',spec.storage?spec.storage+' ГБ':'Не указано на странице')}${renderReqLine('ОС',spec.os)}<p class="requirement-note">${escapeHtml(spec.notes||'')}</p></div>`;}
function checkValue(value, minimum, label, unit=''){if(value===null||value===undefined||value==='')return {state:'unknown',title:'Не указано',detail:`Не указано ${label.toLowerCase()}.`};const pass=value>=minimum;return {state:pass?'good':'bad',title:pass?'Не ниже минимума':'Ниже минимума',detail:`${label}: ${value}${unit}; требуется минимум ${minimum}${unit}.`};}
function osCheck(os, reqOs){if(os==='unknown')return {state:'unknown',title:'Не указана',detail:'Операционная система не указана.'};const windows=['win10','win11'];if((os==='mac'&&/macos/i.test(reqOs))||(os==='linux'&&/linux/i.test(reqOs)))return {state:'good',title:'ОС указана в списке',detail:'Эта операционная система упомянута на странице требований; проверь точную версию.'};if(reqOs.toLowerCase().includes('windows')){if(windows.includes(os))return {state:'good',title:'Windows',detail:'Указана Windows 10/11. Точная версия и сборка могут иметь значение.'};return {state:'bad',title:'Возможно, несовместима',detail:'Введённая ОС отличается от опубликованного требования Windows.'};}if(os==='mac'||os==='linux')return {state:'unknown',title:'Проверь вручную',detail:'Нужно сверить конкретную ОС и версию с источником.'};return {state:'unknown',title:'Не указана',detail:'ОС не удалось проверить.'};}
function itemHtml(label,result){return `<div class="check-item ${result.state}"><span>${label}</span><b>${escapeHtml(result.title)}</b><p>${escapeHtml(result.detail)}</p></div>`;}
function runCheck(){savePc(false);const g=getGame($('quickGameSelect').value);const pc=getPc();if(!g.min){$('resultPanel').classList.remove('hidden');$('resultPanel').innerHTML=`<div class="result-head"><div><div class="panel-kicker">ПРЕДВАРИТЕЛЬНАЯ ПРОВЕРКА</div><h3>${g.emoji} ${escapeHtml(g.name)}</h3><p class="result-summary">Системные требования этой игры ещё не подтверждены в базе GameFit, поэтому честный автоматический результат пока невозможен.</p></div><span class="result-badge badge-warn">Данные не проверены</span></div><div class="result-next"><b>Что можно сделать?</b><p>Открой страницу игры и сверь минимальные требования вручную. Автоматическая проверка появится после проверки надёжного источника.</p><a class="button secondary" href="${g.url}" target="_blank" rel="noopener noreferrer">Найти игру в Steam ↗</a></div>`;$('resultPanel').scrollIntoView({behavior:'smooth',block:'nearest'});return;}const checks=[];const requiredRam=(g.id==='minecraft-java'&&pc.gpuType==='integrated')?12:g.min.ram;checks.push(['RAM',checkValue(pc.ram,requiredRam,'RAM',' ГБ')]);if(g.min.storage!==null)checks.push(['Диск',checkValue(pc.storage,g.min.storage,'Свободное место',' ГБ')]);else checks.push(['Диск',{state:'unknown',title:'Не указано в требованиях',detail:'Источник не указывает минимальный объём места в выбранной карточке.'}]);checks.push(['CPU',{state:'unknown',title:pc.cpu?'Нужно сравнить вручную':'Не указан',detail:pc.cpu?`Введено: ${pc.cpu}. GameFit пока не имеет проверенной базы производительности процессоров.`:'Укажи модель процессора и сравни её с требованиями игры.'}]);checks.push(['GPU',{state:'unknown',title:pc.gpu?'Нужно сравнить вручную':'Не указана',detail:pc.gpu?`Введено: ${pc.gpu}. Точное сравнение видеокарт требует проверенной базы и не сводится к названию.`:'Укажи модель видеокарты и сравни её с требованиями игры.'}]);checks.push(['ОС',osCheck(pc.os,g.min.os)]);
  const fail=checks.some(x=>x[1].state==='bad');const unknown=checks.some(x=>x[1].state==='unknown');let badge,title,summary;if(fail){badge='badge-bad';title='Есть параметр ниже минимума';summary='По введённым данным обнаружено хотя бы одно несовпадение с минимальными требованиями. Это ещё не полноценный тест производительности.';}else if(unknown){badge='badge-warn';title='Нужны дополнительные проверки';summary='Проверенные числовые параметры не ниже минимума, но CPU/GPU или другие пункты ещё не подтверждены. Нельзя гарантировать запуск.';}else{badge='badge-good';title='Все введённые параметры совпали';summary='По проверенным пунктам значения не ниже минимума. Это не гарантия стабильного FPS или отсутствия проблем.';}
  $('resultPanel').classList.remove('hidden');$('resultPanel').innerHTML=`<div class="result-head"><div><div class="panel-kicker">РЕЗУЛЬТАТ ПРЕДВАРИТЕЛЬНОЙ ПРОВЕРКИ</div><h3>${g.emoji} ${escapeHtml(g.name)}</h3><p class="result-summary">${escapeHtml(summary)}</p></div><span class="result-badge ${badge}">${escapeHtml(title)}</span></div><div class="check-grid">${checks.map(([l,r])=>itemHtml(l,r)).join('')}</div><div class="result-next"><b>Что делать дальше?</b><p>Сверь модели процессора и видеокарты с требованиями в официальном источнике. Не покупай игру только на основании этой автоматической проверки.</p><div class="result-buttons"><a class="button secondary" href="${g.url}" target="_blank" rel="noopener noreferrer">Официальные требования ↗</a><button class="button secondary" id="downloadReport">Скачать отчёт</button></div></div><p class="result-foot">GameFit не отправляет данные компьютера на сервер. Текущий алгоритм не рассчитывает FPS, не измеряет производительность и не проверяет драйверы, DirectX, нагрев или фактическое состояние устройства.</p>`;$('downloadReport').addEventListener('click',()=>downloadReport(g,checks,title));$('resultPanel').scrollIntoView({behavior:'smooth',block:'nearest'});}
function downloadReport(game,checks,status){const pc=getPc();const lines=[`GameFit — отчёт проверки`,`Игра: ${game.name}`,`Дата: ${new Date().toLocaleDateString('ru-RU')}`,`Результат: ${status}`,'',`CPU: ${pc.cpu||'не указано'}`,`GPU: ${pc.gpu||'не указано'}`,`RAM: ${pc.ram?pc.ram+' ГБ':'не указано'}`,`Свободное место: ${pc.storage?pc.storage+' ГБ':'не указано'}`,`ОС: ${pc.os}`, '', 'Параметры:',...checks.map(([l,r])=>`${l}: ${r.title} — ${r.detail}`),'',`Источник требований: ${game.url}`,'','Важно: это предварительное сравнение требований, а не тест FPS и не гарантия запуска.'];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`GameFit-${game.id}-report.txt`;a.click();URL.revokeObjectURL(url);toast('Отчёт сохранён.');}
function detectHardware(){const out=[];const ram=navigator.deviceMemory;if(ram){out.push(`Браузер сообщил около ${ram} ГБ доступной памяти (это приблизительная оценка, не точный объём установленной RAM). Не подставляю её в проверку автоматически — точное значение лучше посмотреть в Windows.`);}else out.push('Браузер не сообщил приблизительный объём памяти.');const threads=navigator.hardwareConcurrency;if(threads)out.push(`Обнаружено логических потоков CPU: ${threads}. Это не название и не модель процессора.`);else out.push('Число логических потоков CPU недоступно.');let gpu='';try{const canvas=document.createElement('canvas');const gl=canvas.getContext('webgl')||canvas.getContext('experimental-webgl');if(gl){const ext=gl.getExtension('WEBGL_debug_renderer_info');if(ext)gpu=gl.getParameter(ext.UNMASKED_RENDERER_WEBGL)||'';}}catch(_){}if(gpu){out.push(`Графический адаптер, сообщённый браузером: ${gpu}. Браузер может показывать общее название или виртуальный адаптер.`);if(!$('gpuInput').value)$('gpuInput').value=gpu;}else out.push('Браузер не раскрыл точное название видеокарты.');out.push('ОС не выбирается автоматически: браузер не всегда различает версии Windows.');$('detectOutput').textContent=out.join(' ');$('detectOutput').classList.remove('hidden');savePc(false);toast('Собрана только доступная браузеру информация.');}
function clearPc(){['cpuInput','gpuInput','ramInput','storageInput'].forEach(id=>$(id).value='');$('osInput').value='unknown';$('gpuTypeInput').value='unknown';safeWrite(STORAGE_KEYS.pc,{});queueCloudSync();$('resultPanel').classList.add('hidden');$('detectOutput').classList.add('hidden');toast('Поля профиля очищены.');}
function initTheme(){const theme=safeRead(STORAGE_KEYS.theme,'dark');if(theme==='light')document.body.classList.add('light');$('themeToggle').textContent=document.body.classList.contains('light')?'◐':'☼';}
function toggleTheme(){const light=document.body.classList.toggle('light');safeWrite(STORAGE_KEYS.theme,light?'light':'dark');$('themeToggle').textContent=light?'◐':'☼';queueCloudSync();}
function initEvents(){
  $('savePcBtn').addEventListener('click',()=>savePc());$('clearPcBtn').addEventListener('click',clearPc);$('detectBtn').addEventListener('click',detectHardware);$('quickGameSelect').addEventListener('change',updateQuickPreview);$('quickCheckBtn').addEventListener('click',runCheck);$('gameSearch').addEventListener('input',renderGames);$('themeToggle').addEventListener('click',toggleTheme);$('menuToggle').addEventListener('click',()=>$('mainNav').classList.toggle('open'));
  $('filterRow').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;activeFilter=b.dataset.filter;document.querySelectorAll('.filter-chip').forEach(x=>x.classList.toggle('active',x===b));renderGames();});
  $('gameGrid').addEventListener('click',e=>{const open=e.target.closest('[data-open-game]');const fav=e.target.closest('[data-fav]');if(open)openGameDetail(open.dataset.openGame);if(fav)toggleFavorite(fav.dataset.fav);});
  ['cpuInput','gpuInput','ramInput','storageInput','osInput','gpuTypeInput'].forEach(id=>$(id).addEventListener('change',()=>savePc(false)));
  document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>$('mainNav').classList.remove('open')));
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installBtn').classList.remove('hidden');});
  $('installBtn').addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('installBtn').classList.add('hidden');});
}
function registerServiceWorker(){if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});}
function init(){loadPc();initTheme();renderQuickSelect();renderGames();initEvents();initAuth();registerServiceWorker();}
document.addEventListener('DOMContentLoaded',init);
